<script setup lang="ts">import{ref}from'vue';import{useRouter}from'vue-router';import{api}from'../api';const router=useRouter(),username=ref('admin'),password=ref('Admin123!'),error=ref('');async function login(){try{const{data}=await api.post('/auth/login',{username:username.value,password:password.value});sessionStorage.setItem('admin_access_token',data.accessToken);sessionStorage.setItem('admin_permissions',JSON.stringify(data.user.permissions));router.push('/')}catch{error.value='账号或密码错误'}}</script><template><div class="login"><h1>管理后台</h1><p>主播圈独立运营控制台</p><el-input v-model="username" aria-label="账号"/><el-input v-model="password" type="password" show-password aria-label="密码"/><el-alert v-if="error" :title="error" type="error"/><el-button type="primary" style="width:100%;margin-top:16px" @click="login">登录</el-button></div></template>
